-- Resolve columns to flattened row slots, and validate before any execution.
import Json (..)
import Model (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr { ..e, index = c.index, source = c.source, kind = c.kind }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let kind =
      if e.op == "COUNT" then
        "int"
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> t == "int" || t == "null", ts), "TYPE_ERROR")
        "int"
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(elem(at(ts, 0), ["int", "text", "null"]), "TYPE_ERROR")
        at(ts, 0)
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> t == "bool" || t == "null", ts), "TYPE_ERROR")
        "bool"
      elif elem(e.op, ["ISNULL", "ISNOTNULL"]) then
        "bool"
      elif e.op == "COALESCE" then
        let concrete = filter(\(t) -> t /= "null", ts)
        demand(length(concrete) == 0 || all(\(t) -> t == at(concrete, 0), concrete), "TYPE_ERROR")
        if length(concrete) == 0 then "null" else at(concrete, 0)
      else
        demand(
            (at(ts, 0) == at(ts, 1) || at(ts, 0) == "null" || at(ts, 1) == "null")
              && (at(ts, 0) /= "bool" && at(ts, 1) /= "bool" || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        "bool"
    Expr { ..e, args = args, kind = kind }

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(b.kind == "bool" || b.kind == "null", "TYPE_ERROR")
  b

pub fn tree_any(p : (Expr) -> Bool, e : Expr) : Bool =
  p(e) || any(\(a) -> tree_any(p, a), e.args)

fn grouped(e : Expr, keys : List(Int)) : Unit =
  if not(agg(e.op)) then
    demand(e.op /= "col" || elem(e.index, keys), "INVALID_AGGREGATION")
    for a in sof(e.args) do
      grouped(a, keys)

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

pub fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column { ..at(t.columns, k), index = offset + k, source = i, qualifier = qualifier },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\((n, desc, null_first)) -> (alias_index(aliases, n, 0), desc, null_first), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn alias_index(names : List(String), n : String, i : Int) : Int =
  match names of
    Nil =>
      reject("UNKNOWN_COLUMN")
      -1
    Cons(a, rest) =>
      if a == n then
        i
      else
        alias_index(rest, n, i + 1)

-- The parser owns a scoped token-state effect; all ASTs are immutable values.
import Json (..)
import Data.String (..)
import Data.List (..)
import Data.Foldable (all, length)
import Model (..)
import Control.State (..)

pub type Token = Token { word: String, value: Json }

fn tok(s : String) : Token = Token { word = s, value = JNull }

fn scan_string(s : String, i : Int, acc : String) : (String, Int) =
  demand(i < byte_len(s), "PARSE_ERROR")
  if byte_at(s, i) == 39 then
    if i + 1 < byte_len(s) && byte_at(s, i + 1) == 39 then
      scan_string(s, i + 2, concat(acc, "'"))
    else
      (acc, i + 1)
  else
    scan_string(s, i + 1, concat(acc, str_of_char(chr(byte_at(s, i)))))

fn scan_word(s : String, i : Int, numbers : Bool) : Int =
  if i >= byte_len(s) then
    i
  else
    let c = byte_at(s, i)
    if (digit(c) || not(numbers) && (letter(c) || c >= 65 && c <= 90)) then
      scan_word(s, i + 1, numbers)
    else
      i

fn slice(s : String, i : Int, j : Int) : String =
  string_of_buf(slice_bytes(s, i, j, buf_empty()))

fn lex(s : String, i : Int) : List(Token) =
  if i >= byte_len(s) then
    [tok("$END")]
  else
    let c = byte_at(s, i)
    if elem(c, [32, 9, 10, 13]) then
      lex(s, i + 1)
    elif c == 39 then
      let (v, j) = scan_string(s, i + 1, "")
      Cons(Token { word = "LITERAL", value = JStr(v) }, lex(s, j))
    elif digit(c) then
      let j = scan_word(s, i, true)
      let n =
        match parse_int(slice(s, i, j)) of
          Some(v) => v
          None => 0
      Cons(Token { word = "NUMBER", value = JInt(n) }, lex(s, j))
    elif letter(c) || c >= 65 && c <= 90 then
      let j = scan_word(s, i, false)
      let w = slice(s, i, j)
      Cons(tok(if reserved(w) then to_upper(w) else w), lex(s, j))
    else
      let two = slice(s, i, min(i + 2, byte_len(s)))
      if elem(two, ["<>", "<=", ">="]) then
        Cons(tok(two), lex(s, i + 2))
      else
        demand(
            elem(c, [40, 41, 44, 46, 59, 43, 45, 42, 61, 60, 62]),
            "PARSE_ERROR",
          )
        Cons(tok(str_of_char(chr(c))), lex(s, i + 1))

fn peek() : String ! {State(List(Token))} = at(get(), 0).word

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn accept(w : String) : Bool ! {State(List(Token))} =
  if peek() == w then
    let ts = get()
    put(tail(ts))
    true
  else
    false

fn expect(w : String) : Unit = demand(accept(w), "PARSE_ERROR")

fn name() : String =
  let w = pop().word
  demand(name_ok(w), "PARSE_ERROR")
  w

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn precedence(op : String) : Int =
  if op == "OR" then
    1
  elif op == "AND" then
    2
  elif elem(op, ["=", "<>", "<", ">", "<=", ">="]) then
    4
  elif elem(op, ["+", "-"]) then
    5
  elif op == "*" then
    6
  else
    0

fn expression(minimum : Int) : Expr =
  let t = pop()
  let w = t.word
  let e =
    if w == "NOT" then
      node(w, [expression(3)])
    elif w == "(" then
      let x = expression(1)
      expect(")")
      x
    elif w == "-" then
      literal(JInt(-natural()))
    elif elem(w, ["NUMBER", "LITERAL"]) then
      literal(t.value)
    elif elem(w, ["TRUE", "FALSE"]) then
      literal(JBool(w == "TRUE"))
    elif w == "NULL" then
      literal(JNull)
    elif w == "COALESCE" then
      expect("(")
      let first = expression(1)
      expect(",")
      let second = expression(1)
      let rest = coalesce_tail()
      expect(")")
      node("COALESCE", append([first, second], rest))
    elif agg(w) then
      expect("(")
      let args =
        if w == "COUNT" && accept("*") then
          []
        else
          [expression(1)]
      expect(")")
      node(w, args)
    else
      demand(name_ok(w), "PARSE_ERROR")
      if accept(".") then
        column_ref(w, name())
      else
        column_ref("", w)
  binary(e, minimum, false)

fn coalesce_tail() : List(Expr) =
  if accept(",") then
    Cons(expression(1), coalesce_tail())
  else
    []

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  if op == "IS" then
    demand(not(compared) && 4 >= minimum, "PARSE_ERROR")
    let ignored = pop()
    let negated = accept("NOT")
    expect("NULL")
    binary(node(if negated then "ISNOTNULL" else "ISNULL", [left]), minimum, true)
  else
    let p = precedence(op)
    if p < minimum then
      left
    else
      demand(not(p == 4 && compared), "PARSE_ERROR")
      let ignored = pop()
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Bool, Bool)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let null_first =
    if accept("NULLS") then
      if accept("FIRST") then
        true
      else
        expect("LAST")
        false
    else
      desc
  Cons((n, desc, null_first), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr), ls : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  if elem(peek(), ["INNER", "JOIN"]) then
    let ignored = accept("INNER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [false]))
  elif peek() == "LEFT" then
    let ignored = pop()
    let ignored_outer = accept("OUTER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [true]))
  else
    (ss, js, ls)

fn query() : Query =
  expect("SELECT")
  let distinct = accept("DISTINCT")
  let sels = selections()
  expect("FROM")
  let (ss, js, ls) = join_sources([source()], [], [])
  let pred =
    if accept("WHERE") then
      expression(1)
    else
      literal(JBool(true))
  let groups =
    if accept("GROUP") then
      expect("BY")
      group_keys()
    else
      []
  let hh = accept("HAVING")
  let hav =
    if hh then
      expression(1)
    else
      literal(JBool(true))
  let order =
    if accept("ORDER") then
      expect("BY")
      order_keys()
    else
      []
  let lim =
    if accept("LIMIT") then
      natural()
    else
      -1
  let off =
    if lim >= 0 && accept("OFFSET") then
      natural()
    else
      0
  let ignored = accept(";")
  demand(peek() == "$END", "PARSE_ERROR")
  Query {
    select = sels,
    sources = ss,
    joins = js,
    left_joins = ls,
    predicate = pred,
    groups = groups,
    having = hav,
    has_having = hh,
    order = order,
    distinct = distinct,
    limit = lim,
    offset = off
  }

pub fn parse_sql(s : String) : Query = eval_state(lex(s, 0), query)

-- One request, one response. Domain effects abort the complete query batch.
import Json (..)
import Model (..)
import Parser (..)
import Binder (..)
import Engine (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn input_has(j : Json, key : String) : Bool =
  match j of
    JObj(xs) => length(filter(\(x) -> fst(x) == key, xs)) == 1
    _ => false

fn command_fields(j : Json, names : List(String)) : Unit =
  match j of
    JObj(xs) =>
      demand(length(xs) == length(names), "INVALID_COMMAND")
      demand(all(\(n) -> length(filter(\(x) -> fst(x) == n, xs)) == 1, names), "INVALID_COMMAND")
    _ => reject("INVALID_COMMAND")

fn command_field(j : Json, key : String) : Json =
  match j of
    JObj(xs) =>
      let found = filter(\(x) -> fst(x) == key, xs)
      demand(length(found) == 1, "INVALID_COMMAND")
      snd(at(found, 0))
    _ =>
      reject("INVALID_COMMAND")
      JNull

fn command_text(j : Json) : String =
  match j of
    JStr(s) => s
    _ =>
      reject("INVALID_COMMAND")
      ""

fn command_arr(j : Json) : List(Json) =
  match j of
    JArr(xs) => xs
    _ =>
      reject("INVALID_COMMAND")
      []

fn command_bool(j : Json) : Bool =
  match j of
    JBool(b) => b
    _ =>
      reject("INVALID_COMMAND")
      false

fn bare_name(s : String) : Bool =
  byte_len(s) > 0 && letter(byte_at(s, 0))
    && all(\(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)), range(0, byte_len(s)))

fn view_name(s : String) : Bool =
  byte_len(s) > 0 && byte_len(s) <= 40 && byte_at(s, 0) >= 97 && byte_at(s, 0) <= 122
    && all(\(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)) || byte_at(s, i) == 45, range(0, byte_len(s)))

fn live_tables(database : List(Table)) : List(LiveTable) =
  map(\(t) -> LiveTable { schema = t, rows = map(\(r) -> StoredRow { id = r + 1, row = at(t.rows, r) }, range(0, length(t.rows))), used = range(1, length(t.rows) + 1), next_id = length(t.rows) + 1 }, database)

fn material_database(ts : List(LiveTable)) : List(Table) =
  map(\(t) -> Table { ..t.schema, rows = map(\(r) -> r.row, t.rows) }, ts)

fn reply(value : Json) : Json = JObj([("ok", JBool(true)), ("result", value)])
fn command_error(code : String) : Json = JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn find_live(ts : List(LiveTable), name : String) : LiveTable =
  let xs = filter(\(t) -> t.schema.name == name, ts)
  demand(length(xs) > 0, "UNKNOWN_TABLE")
  at(xs, 0)

fn view_exists(vs : List(View), name : String) : Bool = length(filter(\(v) -> v.name == name, vs)) > 0
fn find_view(vs : List(View), name : String) : View =
  let xs = filter(\(v) -> v.name == name, vs)
  demand(length(xs) > 0, "UNKNOWN_VIEW")
  at(xs, 0)

fn validate_row(schema : Table, row : Json) : List(Json) =
  let xs =
    match row of
      JArr(rs) => rs
      _ =>
        reject("INVALID_ROW")
        []
  demand(length(xs) == length(schema.columns), "INVALID_ROW")
  for i in srange(0, length(xs)) do
    demand(value_type(at(xs, i)) == at(schema.columns, i).kind || value_type(at(xs, i)) == "null" && at(schema.columns, i).nullable, "INVALID_ROW")
  xs

fn update_rows(rows : List(StoredRow), id : Int, row : List(Json)) : List(StoredRow) =
  map(\(r) -> if r.id == id then StoredRow { ..r, row = row } else r, rows)
fn delete_rows(rows : List(StoredRow), id : Int) : List(StoredRow) = filter(\(r) -> r.id /= id, rows)
fn row_present(rows : List(StoredRow), id : Int) : Bool = length(filter(\(r) -> r.id == id, rows)) > 0
fn replace_table(ts : List(LiveTable), changed : LiveTable) : List(LiveTable) = map(\(t) -> if t.schema.name == changed.schema.name then changed else t, ts)

fn sources_of(p : Plan) : List(String) = map(fst, p.query.sources)
fn touches(v : View, changed : List(String)) : Bool = any(\(s) -> elem(s, changed), v.sources)

-- Views are materialized. Only plans mentioning a changed base table are rebuilt;
-- read commands are simple snapshot lookup and execute no query pipeline.
fn refresh_views(vs : List(View), ts : List(LiveTable), changed : List(String)) : List(View) =
  let db = material_database(ts)
  map(\(v) -> if touches(v, changed) then let p = bind(v.plan.query, db) in let p2 = if v.optimized then optimize(p) else p in View { ..v, plan = p2, result = execute(p2) } else v, vs)

fn validate_change_shape(c : Json) : Unit =
  let op = command_text(command_field(c, "op"))
  if op == "insert" || op == "update" then
    command_fields(c, ["op", "table", "id", "row"])
    let table = command_text(command_field(c, "table"))
    demand(bare_name(table), "INVALID_COMMAND")
    match command_field(c, "id") of
      JInt(n) => demand(n >= 1 && n <= 2147483647, "INVALID_COMMAND")
      _ => reject("INVALID_COMMAND")
    let ignored = command_arr(command_field(c, "row"))
    ()
  elif op == "delete" then
    command_fields(c, ["op", "table", "id"])
    let table = command_text(command_field(c, "table"))
    demand(bare_name(table), "INVALID_COMMAND")
    match command_field(c, "id") of
      JInt(n) => demand(n >= 1 && n <= 2147483647, "INVALID_COMMAND")
      _ => reject("INVALID_COMMAND")
    ()
  else
    reject("INVALID_COMMAND")
    ()

fn apply_one(ts : List(LiveTable), c : Json) : List(LiveTable) =
  let op = command_text(command_field(c, "op") )
  let name = command_text(command_field(c, "table"))
  let id =
    match command_field(c, "id") of
      JInt(n) => n
      _ => 0
  let t = find_live(ts, name)
  if op == "insert" then
    let row = validate_row(t.schema, command_field(c, "row"))
    demand(not(elem(id, t.used)), "ROW_ID_USED")
    replace_table(ts, LiveTable { ..t, rows = append(t.rows, [StoredRow { id = id, row = row }]), used = append(t.used, [id]), next_id = max(t.next_id, id + 1) })
  elif op == "update" then
    let row = validate_row(t.schema, command_field(c, "row"))
    demand(row_present(t.rows, id), "UNKNOWN_ROW")
    replace_table(ts, LiveTable { ..t, rows = update_rows(t.rows, id, row) })
  else
    demand(row_present(t.rows, id), "UNKNOWN_ROW")
    replace_table(ts, LiveTable { ..t, rows = delete_rows(t.rows, id) })

fn apply_all(ts : List(LiveTable), cs : List(Json)) : List(LiveTable) =
  match cs of
    Nil => ts
    Cons(c, rest) => apply_all(apply_one(ts, c), rest)

fn changed_tables(cs : List(Json)) : List(String) =
  match cs of
    Nil => []
    Cons(c, rest) =>
      let n = command_text(command_field(c, "table"))
      let later = changed_tables(rest)
      if elem(n, later) then later else Cons(n, later)

fn run_command(c : Json, ts : List(LiveTable), vs : List(View), revision : Int) : CommandOutcome =
  let op = command_text(command_field(c, "op"))
  if op == "create" then
    command_fields(c, ["op", "view", "sql", "optimize"])
    let n = command_text(command_field(c, "view"))
    demand(view_name(n), "INVALID_COMMAND")
    demand(not(view_exists(vs, n)), "VIEW_EXISTS")
    let optimized = command_bool(command_field(c, "optimize"))
    let p = bind(parse_sql(command_text(command_field(c, "sql"))), material_database(ts))
    let p2 = if optimized then optimize(p) else p
    let v = View { name = n, plan = p2, result = execute(p2), sources = sources_of(p2), optimized = optimized }
    CommandOutcome { tables = ts, views = append(vs, [v]), revision = revision, response = reply(JObj([("view", JStr(n)), ("revision", JInt(revision))])) }
  elif op == "read" then
    command_fields(c, ["op", "view"])
    let v = find_view(vs, command_text(command_field(c, "view")))
    let result =
      match v.result of
        JObj(xs) => JObj([("revision", JInt(revision)), ("columns", snd(at(xs, 0))), ("rows", snd(at(xs, 1)))])
        _ => v.result
    CommandOutcome { tables = ts, views = vs, revision = revision, response = reply(result) }
  elif op == "drop" then
    command_fields(c, ["op", "view"])
    let n = command_text(command_field(c, "view"))
    let ignored = find_view(vs, n)
    CommandOutcome { tables = ts, views = filter(\(v) -> v.name /= n, vs), revision = revision, response = reply(JObj([("dropped", JStr(n))])) }
  elif op == "apply" then
    command_fields(c, ["op", "changes"])
    let cs = command_arr(command_field(c, "changes"))
    demand(length(cs) > 0 && length(cs) <= 200, "INVALID_COMMAND")
    for x in sof(cs) do validate_change_shape(x)
    let next = apply_all(ts, cs)
    let nr = revision + 1
    CommandOutcome { tables = next, views = refresh_views(vs, next, changed_tables(cs)), revision = nr, response = reply(JObj([("revision", JInt(nr))])) }
  else
    reject("INVALID_COMMAND")
    CommandOutcome { tables = ts, views = vs, revision = revision, response = command_error("INVALID_COMMAND") }

fn commands_loop(cs : List(Json), ts : List(LiveTable), vs : List(View), revision : Int) : List(Json) =
  match cs of
    Nil => []
    Cons(c, rest) =>
      let outcome =
        handle run_command(c, ts, vs, revision) with
          never reject(code) => CommandOutcome { tables = ts, views = vs, revision = revision, response = command_error(code) }
          return x => x
      Cons(outcome.response, commands_loop(rest, outcome.tables, outcome.views, outcome.revision))


fn work_commands(input : Json, database : List(Table)) : Json =
  fields(input, ["database", "commands"])
  let results = commands_loop(command_arr(command_field(input, "commands")), live_tables(database), [], 0)
  JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn work(request : Json) : Json =
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  demand(input_has(input, "database") && (input_has(input, "queries") || input_has(input, "commands")), "INVALID_INPUT")
  let database = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, database)), "INVALID_INPUT")
  if input_has(input, "commands") then
    work_commands(input, database)
  else
    fields(input, ["database", "queries"])
    let queries = arr(getfield(input, "queries"))
    for q in sof(queries) do
      validate_query(q)
    let results = map(
        \(q) -> let plan = bind(parse_sql(text(getfield(q, "sql"))), database) in execute(if truth(getfield(q, "optimize")) then optimize(plan) else plan),
        queries,
      )
    JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn error_response(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn decode_work(line : String) : Json =
  match decode_lossy(line) of
    Ok(request) => work(request)
    Err(_) => error_response("INVALID_INPUT")

fn main() =
  let line = read_line()
  let response =
    handle decode_work(line) with
      never reject(code) => error_response(code)
      return result => result
  println(encode(response))

